package com.ci.pipeline

import java.io.File
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicReference
import java.util.concurrent.ConcurrentHashMap
import sun.misc.Signal
import sun.misc.SignalHandler

data class FeatureFlags(
    val enableGracefulShutdown: Boolean = true,
    val enableArtifactCleanup: Boolean = true,
    val enableMetricsFlush: Boolean = true,
    val shutdownTimeoutMs: Long = 5000
)

class PipelineState {
    val artifacts = ConcurrentHashMap<String, File>()
    val credentials = AtomicReference<String?>(null)
    val metricsBuffer = mutableListOf<String>()
    val isShuttingDown = AtomicBoolean(false)
    val cleanupComplete = AtomicBoolean(false)
}

class ArtifactManager(private val state: PipelineState) {
    fun registerArtifact(name: String, path: String) {
        val file = File(path)
        state.artifacts[name] = file
    }

    fun cleanupArtifacts(): List<String> {
        val cleaned = mutableListOf<String>()
        val iterator = state.artifacts.entries.iterator()
        while (iterator.hasNext()) {
            val entry = iterator.next()
            if (entry.value.exists()) {
                entry.value.delete()
                cleaned.add(entry.key)
            }
            iterator.remove()
        }
        return cleaned
    }
}

class MetricsCollector(private val state: PipelineState) {
    fun record(metric: String) {
        synchronized(state.metricsBuffer) {
            state.metricsBuffer.add(metric)
        }
    }

    fun flush(): List<String> {
        synchronized(state.metricsBuffer) {
            val copy = state.metricsBuffer.toList()
            state.metricsBuffer.clear()
            return copy
        }
    }
}

class CredentialStore(private val state: PipelineState) {
    fun loadCredentials(token: String) {
        state.credentials.set(token)
    }

    fun revokeCredentials() {
        state.credentials.set(null)
    }

    fun getCredentials(): String? = state.credentials.get()
}

class ShutdownCoordinator(
    private val state: PipelineState,
    private val artifactManager: ArtifactManager,
    private val metricsCollector: MetricsCollector,
    private val credentialStore: CredentialStore,
    private val flags: FeatureFlags
) {
    private val tempLogFile = AtomicReference<File?>(null)

    fun performShutdown() {
        if (!state.isShuttingDown.compareAndSet(false, true)) {
            return
        }

        if (flags.enableMetricsFlush) {
            val metrics = metricsCollector.flush()
            writeShutdownLog("Flushed ${metrics.size} metrics")
        }

        if (flags.enableArtifactCleanup) {
            val cleaned = artifactManager.cleanupArtifacts()
            writeShutdownLog("Cleaned ${cleaned.size} artifacts")
        }

        // Revoke credentials after cleanup to ensure authenticated cleanup ops succeed
        credentialStore.revokeCredentials()
        state.cleanupComplete.set(true)
    }

    private fun writeShutdownLog(message: String) {
        val logFile = tempLogFile.get() ?: run {
            val f = File.createTempFile("pipeline_shutdown_", ".log")
            tempLogFile.set(f)
            f
        }
        logFile.appendText("$message\n")
    }
}

class PipelineRunner(private val flags: FeatureFlags) {
    private val state = PipelineState()
    private val artifactManager = ArtifactManager(state)
    private val metricsCollector = MetricsCollector(state)
    private val credentialStore = CredentialStore(state)
    private val shutdownCoordinator = ShutdownCoordinator(
        state, artifactManager, metricsCollector, credentialStore, flags
    )

    fun initialize(token: String) {
        credentialStore.loadCredentials(token)
        installSignalHandlers()
    }

    private fun installSignalHandlers() {
        if (flags.enableGracefulShutdown) {
            val handler = SignalHandler { sig ->
                shutdownCoordinator.performShutdown()
                // Re-raise to allow default handling after cleanup
                Signal.raise(sig)
            }
            Signal.handle(Signal("TERM"), handler)
            Signal.handle(Signal("INT"), handler)
        }
    }

    fun runStage(stageName: String, block: (ArtifactManager, CredentialStore) -> Unit) {
        if (state.isShuttingDown.get()) {
            throw IllegalStateException("Pipeline is shutting down")
        }
        metricsCollector.record("stage_start:$stageName:${System.currentTimeMillis()}")
        try {
            block(artifactManager, credentialStore)
            metricsCollector.record("stage_end:$stageName:${System.currentTimeMillis()}")
        } catch (e: Exception) {
            metricsCollector.record("stage_error:$stageName:${e.message}")
            throw e
        }
    }

    fun shutdown() {
        shutdownCoordinator.performShutdown()
    }
}

fun main() {
    val flags = FeatureFlags(
        enableGracefulShutdown = true,
        enableArtifactCleanup = true,
        enableMetricsFlush = true
    )

    val runner = PipelineRunner(flags)
    runner.initialize(System.getenv("CI_TOKEN") ?: "default-token")

    runner.runStage("build") { artifacts, creds ->
        artifacts.registerArtifact("binary", "/tmp/build/output.bin")
        println("Build complete with creds: ${creds.getCredentials()?.take(4)}...")
    }

    runner.runStage("deploy") { artifacts, creds ->
        val token = creds.getCredentials()
        println("Deploying with token present: ${token != null}")
    }

    runner.shutdown()
}
